// The concatenated representation covers the ISO 3166-1 alpha-2 assignments
// verified on 2026-09-21 without allocating or accepting private-use codes.
const ISO_3166_ALPHA_2: &str = "";

pub(crate) fn is_iso_3166_alpha_2(value: &str) -> bool {
    value.len() == 2
        && value.bytes().all(|byte| byte.is_ascii_uppercase())
        && ISO_3166_ALPHA_2
            .as_bytes()
            .as_chunks::<2>()
            .0
            .iter()
            .any(|candidate| candidate.as_slice() == value.as_bytes())
}
